CREATE FUNCTION public.owner85_fail_audit() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.action_type='organization.owner_add' THEN RAISE EXCEPTION 'fixture_audit_failed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER owner85_fail_audit BEFORE INSERT ON public.audit_events FOR EACH ROW EXECUTE FUNCTION public.owner85_fail_audit();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"85000000-0000-0000-0000-000000000001","role":"authenticated","session_id":"owner85-session1"}',true);
SELECT throws_ok($$ SELECT public.add_organization_owner_atomic('85000000-0000-0000-0000-00000000000a','85000000-0000-0000-0000-000000000002','audit-failure') $$,'P0001','fixture_audit_failed','failed audit rolls back owner addition');
RESET ROLE;
SELECT is((SELECT role FROM public.organization_members WHERE organization_id='85000000-0000-0000-0000-00000000000a' AND user_id='85000000-0000-0000-0000-000000000002'),'member','failed audit leaves member unchanged');
SELECT ok((SELECT used_at IS NULL FROM public.reauth_grants WHERE token_hash=encode(extensions.digest('audit-failure','sha256'),'hex')),'failed audit leaves grant unused');
DROP TRIGGER owner85_fail_audit ON public.audit_events;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"85000000-0000-0000-0000-000000000001","role":"authenticated","session_id":"owner85-session1"}',true);
SELECT lives_ok($$ SELECT public.add_organization_owner_atomic('85000000-0000-0000-0000-00000000000a','85000000-0000-0000-0000-000000000002','good') $$,'owner can add a member after reauthentication');
SELECT throws_ok($$ SELECT public.add_organization_owner_atomic('85000000-0000-0000-0000-00000000000a','85000000-0000-0000-0000-000000000003','good') $$,'P0001','owner_add_requires_reauthentication','successful grant cannot be replayed for another target');
SELECT throws_ok($$ SELECT public.add_organization_owner_atomic('85000000-0000-0000-0000-00000000000a','85000000-0000-0000-0000-000000000002','another') $$,'P0001','invalid_owner_add_target','already-owner target rejected');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM public.organization_members WHERE organization_id='85000000-0000-0000-0000-00000000000a' AND role='owner'),2,'both owners remain owners');
SELECT is((SELECT count(*)::integer FROM public.organization_member_roles WHERE organization_id='85000000-0000-0000-0000-00000000000a' AND user_id='85000000-0000-0000-0000-000000000002'),1,'business role assignment retained');
SELECT is((SELECT user_id FROM public.staffs WHERE id='85000000-0000-0000-0000-000000000020'),'85000000-0000-0000-0000-000000000002'::uuid,'staff association retained');
SELECT is((SELECT count(*)::integer FROM public.audit_events WHERE organization_id='85000000-0000-0000-0000-00000000000a' AND action_type='organization.owner_add'),1,'exactly one success audit');
SELECT ok(EXISTS(SELECT 1 FROM public.audit_events WHERE organization_id='85000000-0000-0000-0000-00000000000a' AND actor_id='85000000-0000-0000-0000-000000000001' AND resource_id='85000000-0000-0000-0000-000000000002' AND session_id='owner85-session1' AND details->>'beforeRole'='member' AND details->>'afterRole'='owner' AND outcome='success'),'audit identifies actor target session and role change');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"85000000-0000-0000-0000-000000000003","role":"authenticated","session_id":"owner85-session3"}',true);
SELECT throws_ok($$ SELECT public.account_remove('85000000-0000-0000-0000-00000000000a','85000000-0000-0000-0000-000000000002','active') $$,'42501','owner_required','accounts manager cannot remove an owner');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"85000000-0000-0000-0000-000000000001","role":"authenticated","session_id":"owner85-session1"}',true);
SELECT lives_ok($$ SELECT public.leave_organization_atomic('85000000-0000-0000-0000-00000000000a') $$,'one owner may withdraw while another remains');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"85000000-0000-0000-0000-000000000002","role":"authenticated","session_id":"owner85-session2"}',true);
SELECT throws_ok($$ SELECT public.account_remove('85000000-0000-0000-0000-00000000000a','85000000-0000-0000-0000-000000000002','active') $$,'P0001','last_owner','last owner cannot be removed');
SELECT throws_ok($$ SELECT public.leave_organization_atomic('85000000-0000-0000-0000-00000000000a') $$,'P0001','sole_owner','last owner cannot withdraw');
RESET ROLE;
INSERT INTO public.reauth_grants(token_hash,user_id,auth_session_id,purpose,expires_at)
VALUES(encode(extensions.digest('last-owner-delete','sha256'),'hex'),'85000000-0000-0000-0000-000000000002','owner85-session2','account_delete',now()+interval '10 minutes');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$ SELECT public.request_own_account_deletion('fixture retention','last-owner-delete') $$,'P0001','last_owner','last owner cannot delete their account');
SELECT throws_ok($$ DELETE FROM public.organization_members WHERE organization_id='85000000-0000-0000-0000-00000000000a' $$,'42501','permission denied for table organization_members','direct membership DELETE rejected');
SELECT lives_ok($$ SELECT public.create_invitation_authorized('85000000-0000-0000-0000-00000000000a','owner85-join-existing','owner85-4@example.invalid','Joining fixture') $$,'owner can still invite through authorized RPC');
RESET ROLE;
SELECT ok((SELECT used_at IS NULL FROM public.reauth_grants WHERE token_hash=encode(extensions.digest('last-owner-delete','sha256'),'hex')),'rejected last-owner account deletion preserves grant');
SELECT ok((SELECT deleted_at IS NULL FROM public.profiles WHERE id='85000000-0000-0000-0000-000000000002'),'rejected last-owner account deletion preserves profile');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"85000000-0000-0000-0000-000000000004","role":"authenticated","email":"owner85-4@example.invalid","session_id":"owner85-session4"}',true);
SELECT lives_ok($$ SELECT public.accept_invitation_atomic('owner85-join-existing','owner85-session4') $$,'invitation acceptance still works without direct membership DML');
SELECT lives_ok($$ SELECT public.create_organization('Owner85 bootstrap fixture') $$,'initial owner can still be created through organization RPC');
RESET ROLE;
SELECT is((SELECT role FROM public.organization_members WHERE organization_id='85000000-0000-0000-0000-00000000000a' AND user_id='85000000-0000-0000-0000-000000000004'),'member','invitation cannot implicitly add an owner');
SELECT is((SELECT m.role FROM public.organization_members m JOIN public.organizations o ON o.id=m.organization_id WHERE o.name='Owner85 bootstrap fixture' AND m.user_id='85000000-0000-0000-0000-000000000004'),'owner','organization creator retains initial ownership');
SELECT * FROM finish();
ROLLBACK;
